INSERT INTO comments VALUES (1, 1, 6, NULL, 'This helped me a lot before my midterm, thank you!', '2025-02-02 01:02:00');
INSERT INTO comments VALUES (2, 2, 11, NULL, 'Clear explanation — finally understood the topic.', '2025-03-03 02:04:00');
INSERT INTO comments VALUES (3, 3, 16, NULL, 'Can you make a follow-up video on the advanced part?', '2025-04-04 03:06:00');
INSERT INTO comments VALUES (4, 4, 21, NULL, 'Subscribed after this, great content as always.', '2025-05-05 04:08:00');
INSERT INTO comments VALUES (5, 5, 26, NULL, 'I tried this at home and it worked first try.', '2025-06-06 05:10:00');
